const COL = { n: 0, hash: 1, date: 2, subject: 3, tag: 4, skills: 5, agents: 6, hooks: 7, claude: 8, specs: 9, srcLoc: 10, rules: 11, tests: 12, mutation: 13, docsCheck: 14, skillLines: 15, agentLines: 16, docLines: 17 };
const GITHUB = "https://github.com/oleg-vasilyev/FoolProof/commit/";
const eraOf = (n) => ERA_ENDS.findIndex((end) => n <= end);
const dayOf = (iso) => { const [, m, d] = iso.split("-").map(Number); return `${d} ${TEXT.months[m - 1]}`; };
const format = (value) => value.toLocaleString(TEXT.locale);
const svgOf = (tag, attributes) => {
  const node = document.createElementNS("http://www.w3.org/2000/svg", tag);
  for (const [name, value] of Object.entries(attributes)) { node.setAttribute(name, String(value)); }
  return node;
};

(function drawTimeline() {
  const host = document.querySelector("[data-timeline]");
  if (!host) { return; }
  const tip = host.querySelector("[data-tl-tip]");
  const W = 1000, H = 92, TOP = 18, BAR_TOP = 26, BAR_H = 34, LABEL_Y = 82;
  const slot = W / DATA.length;
  const svg = svgOf("svg", { viewBox: `0 0 ${W} ${H}`, role: "img", "aria-label": TEXT.timeline });
  const bars = svgOf("g", { "aria-hidden": "true" });
  DATA.forEach((row) => {
    const n = row[COL.n];
    const x = (n - 1) * slot;
    const link = svgOf("a", { href: GITHUB + row[COL.hash], target: "_blank", rel: "noopener", class: "tl-commit", tabindex: "-1" });
    link.appendChild(svgOf("rect", { x: x + 0.4, y: BAR_TOP, width: Math.max(slot - 0.8, 1.2), height: BAR_H, rx: 0.6, fill: ERA_COLOURS[eraOf(n)], opacity: 0.85 }));
    if (row[COL.tag]) {
      link.appendChild(svgOf("path", { d: `M${x + slot / 2} ${TOP - 6} l4 6 l-4 6 l-4 -6 z`, class: "tl-tag" }));
    }
    link.addEventListener("pointerenter", () => show(row, x + slot / 2));
    link.addEventListener("focus", () => show(row, x + slot / 2));
    link.addEventListener("pointerleave", hide);
    link.addEventListener("blur", hide);
    bars.appendChild(link);
  });
  svg.appendChild(bars);
  let start = 1;
  ERA_ENDS.forEach((end, index) => {
    const x0 = (start - 1) * slot, x1 = end * slot;
    svg.appendChild(svgOf("line", { x1: x0 + 1, y1: LABEL_Y - 9, x2: x1 - 1, y2: LABEL_Y - 9, stroke: ERA_COLOURS[index], "stroke-width": 2 }));
    const label = svgOf("text", { x: x0 + 2, y: LABEL_Y + 2, class: "tl-era-label" });
    label.textContent = `${index + 1} · ${dayOf(DATA[start - 1][COL.date])} – ${dayOf(DATA[end - 1][COL.date])}`;
    label.style.cursor = "pointer";
    label.addEventListener("click", () => document.getElementById(`era-${index + 1}`)?.scrollIntoView({ behavior: "smooth" }));
    svg.appendChild(label);
    start = end + 1;
  });
  host.insertBefore(svg, tip);
  function show(row, xUnits) {
    tip.replaceChildren();
    const head = document.createElement("p"); head.className = "chart-tip-head";
    head.textContent = `#${row[COL.n]} · ${row[COL.hash]} · ${dayOf(row[COL.date])}${row[COL.tag] ? " · " + row[COL.tag] : ""}`;
    const body = document.createElement("p"); body.className = "mt-1 text-ink"; body.textContent = row[COL.subject];
    tip.append(head, body);
    tip.hidden = false;
    const width = host.clientWidth;
    const px = (xUnits / W) * width;
    tip.style.top = "0px";
    tip.style.left = `${Math.min(Math.max(px - 100, 0), width - tip.offsetWidth)}px`;
    tip.style.transform = "translateY(calc(-100% - 8px))";
  }
  function hide() { tip.hidden = true; }
  const legend = document.querySelector("[data-tl-legend]");
  TEXT.eras.forEach((name, index) => {
    const item = document.createElement("a");
    item.href = `#era-${index + 1}`;
    item.className = "inline-flex items-center gap-2 hover:text-ink";
    const dot = document.createElement("span"); dot.className = "era-dot"; dot.style.background = ERA_COLOURS[index];
    item.append(dot, document.createTextNode(name));
    legend.appendChild(item);
  });
  const tagKey = document.createElement("span");
  tagKey.className = "inline-flex items-center gap-2";
  tagKey.append(document.createTextNode("◆ " + TEXT.release));
  legend.appendChild(tagKey);
})();

function lineChart(figure, spec) {
  const plot = figure.querySelector(".chart-plot");
  const W = 720, H = 260, L = 46, R = 14, T = 12, B = 30;
  const innerW = W - L - R, innerH = H - T - B;
  const yMin = spec.yMin ?? 0;
  const xOf = (n) => L + ((n - 1) / (DATA.length - 1)) * innerW;
  const yOf = (v) => T + innerH - ((v - yMin) / (spec.yMax - yMin)) * innerH;
  const svg = svgOf("svg", { viewBox: `0 0 ${W} ${H}`, role: "img", "aria-label": spec.label });
  spec.yTicks.forEach((tick) => {
    svg.appendChild(svgOf("line", { x1: L, x2: W - R, y1: yOf(tick), y2: yOf(tick), class: "chart-grid" }));
    const text = svgOf("text", { x: L - 8, y: yOf(tick) + 4, "text-anchor": "end", class: "chart-axis" });
    text.textContent = spec.yFormat ? spec.yFormat(tick) : format(tick);
    svg.appendChild(text);
  });
  ERA_ENDS.slice(0, -1).forEach((end) => {
    svg.appendChild(svgOf("line", { x1: xOf(end + 0.5), x2: xOf(end + 0.5), y1: T, y2: T + innerH, class: "chart-grid", "stroke-dasharray": "2 4" }));
  });
  [1, 60, 120, 180, 240, 274].forEach((n) => {
    const text = svgOf("text", { x: xOf(n), y: H - 8, "text-anchor": n === 1 ? "start" : n === 274 ? "end" : "middle", class: "chart-axis" });
    text.textContent = dayOf(DATA[n - 1][COL.date]);
    svg.appendChild(text);
  });
  (spec.refs ?? []).forEach((ref) => {
    svg.appendChild(svgOf("line", { x1: L, x2: W - R, y1: yOf(ref.y), y2: yOf(ref.y), class: "chart-ref", "stroke-dasharray": "6 4" }));
    const text = svgOf("text", { x: W - R, y: yOf(ref.y) - 5, "text-anchor": "end", class: "chart-ref-label" });
    text.textContent = ref.label;
    svg.appendChild(text);
  });
  spec.series.forEach((series) => {
    const points = DATA.map((row) => [row[COL.n], series.value(row)]).filter(([, v]) => v !== null && v !== undefined);
    if (series.dots) {
      points.forEach(([n, v]) => svg.appendChild(svgOf("circle", { cx: xOf(n), cy: yOf(v), r: 3.5, fill: series.colour, class: "chart-dot" })));
    } else {
      const d = points.map(([n, v], i) => `${i ? "L" : "M"}${xOf(n).toFixed(1)} ${yOf(v).toFixed(1)}`).join(" ");
      svg.appendChild(svgOf("path", { d, class: "chart-line", stroke: series.colour }));
      const [n, v] = points[points.length - 1];
      svg.appendChild(svgOf("circle", { cx: xOf(n), cy: yOf(v), r: 4, fill: series.colour, class: "chart-dot" }));
    }
  });
  const cross = svgOf("line", { x1: 0, x2: 0, y1: T, y2: T + innerH, class: "chart-cross", visibility: "hidden" });
  svg.appendChild(cross);
  const hit = svgOf("rect", { x: L, y: T, width: innerW, height: innerH, fill: "transparent" });
  svg.appendChild(hit);
  plot.appendChild(svg);
  const tip = document.createElement("div"); tip.className = "chart-tip"; tip.hidden = true; plot.appendChild(tip);
  const nearest = (clientX) => {
    const box = svg.getBoundingClientRect();
    const units = ((clientX - box.left) / box.width) * W;
    return Math.min(DATA.length, Math.max(1, Math.round(((units - L) / innerW) * (DATA.length - 1)) + 1));
  };
  const readout = (n) => {
    const row = DATA[n - 1];
    tip.replaceChildren();
    const head = document.createElement("p"); head.className = "chart-tip-head";
    head.textContent = `#${n} · ${dayOf(row[COL.date])}${row[COL.tag] ? " · " + row[COL.tag] : ""}`;
    const subject = document.createElement("p"); subject.className = "mt-1"; subject.textContent = row[COL.subject];
    tip.append(head, subject);
    spec.series.forEach((series) => {
      let value = series.value(row);
      let at = n;
      if (series.dots && value === null) {
        for (let back = n - 1; back >= 1 && value === null; back--) { value = series.value(DATA[back - 1]); at = back; }
      }
      const line = document.createElement("p"); line.className = "chart-tip-row";
      const key = document.createElement("span"); key.className = "chart-key"; key.style.color = series.colour;
      const strong = document.createElement("b"); strong.textContent = value === null || value === undefined ? "—" : (series.format ? series.format(value) : format(value));
      const name = document.createElement("span"); name.textContent = series.name + (series.dots && at !== n ? ` (${TEXT.asOf}${at})` : "");
      line.append(key, strong, name);
      tip.appendChild(line);
    });
    cross.setAttribute("x1", xOf(n)); cross.setAttribute("x2", xOf(n)); cross.setAttribute("visibility", "visible");
    tip.hidden = false;
    const width = plot.clientWidth;
    const px = (xOf(n) / W) * width;
    tip.style.top = "0px";
    tip.style.left = `${px + 14 + tip.offsetWidth > width ? px - tip.offsetWidth - 14 : px + 14}px`;
  };
  hit.addEventListener("pointermove", (event) => readout(nearest(event.clientX)));
  hit.addEventListener("pointerleave", () => { tip.hidden = true; cross.setAttribute("visibility", "hidden"); });
  const legend = figure.querySelector(".chart-legend");
  if (legend && spec.series.length > 1) {
    spec.series.forEach((series) => {
      const item = document.createElement("span");
      const key = document.createElement("span"); key.className = "chart-key"; key.style.color = series.colour;
      item.append(key, document.createTextNode(series.name));
      legend.appendChild(item);
    });
  }
  const details = figure.querySelector(".chart-table");
  const table = document.createElement("table");
  const headRow = document.createElement("tr");
  [TEXT.table.commit, TEXT.table.date, ...spec.series.map((series) => series.name)].forEach((label) => { const th = document.createElement("th"); th.textContent = label; headRow.appendChild(th); });
  table.appendChild(headRow);
  DATA.filter((row) => row[COL.n] % 10 === 0 || row[COL.n] === 1 || row[COL.n] === DATA.length).forEach((row) => {
    const tr = document.createElement("tr");
    [`#${row[COL.n]} ${row[COL.hash]}`, row[COL.date], ...spec.series.map((series) => { const v = series.value(row); return v === null || v === undefined ? "—" : (series.format ? series.format(v) : format(v)); })].forEach((cell) => { const td = document.createElement("td"); td.textContent = cell; tr.appendChild(td); });
    table.appendChild(tr);
  });
  details.appendChild(table);
}

const ACCENT = ERA_COLOURS[3];
const CAT = ERA_COLOURS.slice(0, 3);
const percent = (v) => `${v.toLocaleString(TEXT.locale, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}%`;
const charts = {
  claude: { label: TEXT.charts.claude, yMax: 600, yTicks: [0, 200, 400, 600], refs: [{ y: 380, label: TEXT.series.budget + " 380" }], series: [{ name: TEXT.series.claude, colour: ACCENT, value: (row) => row[COL.claude] }] },
  tests: { label: TEXT.charts.tests, yMax: 4500, yTicks: [0, 1500, 3000, 4500], series: [{ name: TEXT.series.tests, colour: ACCENT, dots: true, value: (row) => row[COL.tests] }] },
  mutation: { label: TEXT.charts.mutation, yMin: 80, yMax: 100, yTicks: [80, 85, 90, 95, 100], yFormat: (v) => `${v}%`, refs: [{ y: 85, label: TEXT.series.threshold + " 85%" }], series: [{ name: TEXT.series.mutation, colour: ACCENT, dots: true, format: percent, value: (row) => row[COL.mutation] }] },
  parts: { label: TEXT.charts.parts, yMax: 12, yTicks: [0, 3, 6, 9, 12], series: [
    { name: TEXT.series.skills, colour: CAT[0], value: (row) => row[COL.skills] },
    { name: TEXT.series.agents, colour: CAT[1], value: (row) => row[COL.agents] },
    { name: TEXT.series.rules, colour: CAT[2], value: (row) => row[COL.rules] },
  ] },
  lines: { label: TEXT.charts.lines, yMax: 16000, yTicks: [0, 4000, 8000, 12000, 16000], series: [
    { name: TEXT.series.src, colour: CAT[0], value: (row) => row[COL.srcLoc] },
    { name: TEXT.series.harness, colour: CAT[1], value: (row) => row[COL.skillLines] + row[COL.agentLines] + row[COL.docLines] + row[COL.docsCheck] },
  ] },
};
document.querySelectorAll("[data-chart]").forEach((figure) => {
  const spec = charts[figure.dataset.chart];
  if (spec) {
    lineChart(figure, spec);
  }
});
